using System;
using Cysharp.Threading.Tasks;
using DG.Tweening;
using UnityEngine;

namespace DogGuns_Games.vamsir
{
    public class NormalMob : VamserMobBase
    {
        [Header("<color=green>플레이어 무기")] 
        private Weaphon_base player_Weaphon;

        //피격 물체가 발사체인지 구분
        private bool _isHitByShoot;

        [Header("몹 스탯")]
        [SerializeField] private float initialHp = 100f;
        [SerializeField] private float initialSpeed = 1f;
        [SerializeField] private float initialAttackDamage = 10f;
        [SerializeField] private float initialAttackSpeed = 1f;
        [SerializeField] private float initialAttackRange = 1f;
        [SerializeField] private float initialStunTime = 0.1f;

        [Header("<color=green>탐색 범위")]
        [SerializeField] private float searchRange = 8f;

        private void Awake()
        {
            DOTween.SetTweensCapacity(500, 50);
        }

        private void Start()
        {
            // Init() 호출을 SetTarget으로 이동하여 player 참조가 보장되도록 합니다.
        }

        private void Init()
        {
            if (player != null)
            {
                player_Weaphon = player.WeaphonBase;
                if (player_Weaphon != null)
                {
                    _isHitByShoot = player_Weaphon.isShooting;
                }
            }

            Mob_Hp = initialHp;
            Mob_Speed = initialSpeed;
            Mob_AttackDamage = initialAttackDamage;
            Mob_AttackSpeed = initialAttackSpeed;
            Mob_AttackRange = initialAttackRange;
            Mob_StunTime = initialStunTime;

            Mob_IsDie = false;
            Mob_IsHit = false;
        }

        public override void SetTarget(PlayerBase target)
        {
            base.SetTarget(target);
            Init();
        }

        public override void OnEnable()
        {
            base.OnEnable();
            // Init() 호출을 SetTarget으로 이동하여 player 참조가 보장되도록 합니다.
            SetMobState(MobState.Move);
        }


        private void FixedUpdate()
        {

            // todo 스폰시 맵 밖이면 맵 안까지 이동

            // 플레이어 탐색 범위 내에 있을 때만 추적 및 공격
            if (!ismove || player == null)
            {
                if (ismove) transform.DOKill();
                return;
            }
            float distanceToPlayer = Vector3.Distance(transform.position, player.transform.position);
            if (distanceToPlayer > searchRange)
            {
                // 플레이어가 탐색 범위 밖에 있으면 추적하지 않음
                return;
            }
            // 플레이어를 추적하는 로직
            Vector3 direction = (player.transform.position - transform.position).normalized;
            transform.position += direction * Mob_Speed * Time.fixedDeltaTime;

            // 플레이어 방향으로 몹 회전 (좌우 반전)
            if (direction.x != 0)
            {
                // direction.x > 0 이면 오른쪽을 보도록 180도 회전 (스프라이트가 왼쪽을 보고 있을 경우)
                // direction.x < 0 이면 왼쪽을 보도록 0도 회전
                float yRotation = direction.x > 0 ? 180f : 0f;
                transform.rotation = Quaternion.Euler(0, yRotation, 0);
            }
        }

        private void OnCollisionEnter2D(Collision2D other)
        {
            if (_isHitByShoot)
            {
                HandleCollision(other);
            }
        }

        private void OnCollisionStay2D(Collision2D other)
        {
            if (!_isHitByShoot)
            {
                HandleCollision(other);
            }
        }

        private void HandleCollision(Collision2D other)
        {
            if (!Mob_IsHit && other.gameObject.CompareTag("Player_Attack"))
            {
                HitCooltime(other).Forget();
                LogManager.Log("_isHitByShoot: "+_isHitByShoot,LogManager.LogCategory.NormalMob);
            }
        }

        private async UniTask HitCooltime(Collision2D other)
        {
            Mob_IsHit = true;

            float attackPower = player_Weaphon.attackPower;
            float stunTime = player_Weaphon.mobStunTime;

            await UniTask.Yield();
            Mob_Hp -= attackPower;

            if (Mob_Hp <= 0)
            {
                SetMobState(MobState.Die);
            }
            else
            {
                Mob_StunTime = stunTime;
                SetMobState(MobState.Stun);
            }

            Mob_IsHit = false;
        }

        protected override void Mob_Idle()
        {
            LogManager.Log("Idle", LogManager.LogCategory.NormalMob);
        }

        protected override void Mob_Move()
        {
            ismove = true;
        }

        protected override void Mob_Stun()
        {
            LogManager.Log("Stun", LogManager.LogCategory.NormalMob);
            ismove = false;
            DOVirtual.DelayedCall(Mob_StunTime, () => { SetMobState(MobState.Move); });
        }

        protected override void Mob_hit()
        {
            base.Mob_hit();
        }

        protected override void Mob_Attack()
        {
            LogManager.Log("Attack", LogManager.LogCategory.NormalMob);
        }

        protected override void Mob_Die()
        {
            base.Mob_Die();
            transform.DOKill();
            LogManager.Log("Die", LogManager.LogCategory.NormalMob);
        }
    }
}

using System;
using Cysharp.Threading.Tasks;
using DG.Tweening;
using UnityEngine;

namespace DogGuns_Games.vamsir
{
    public class NormalMob : VamserMobBase
    {
        [Header("<color=green>플레이어 무기")] 
        private Weaphon_base player_Weaphon;

        //피격 물체가 발사체인지 구분
        private bool _isHitByShoot;

        [Header("몹 스탯")]
        [SerializeField] private float initialHp = 100f;
        [SerializeField] private float initialSpeed = 1f;
        [SerializeField] private float initialAttackDamage = 10f;
        [SerializeField] private float initialAttackSpeed = 1f;
        [SerializeField] private float initialAttackRange = 1f;
        [SerializeField] private float initialStunTime = 0.1f;

        [Header("<color=green>탐색 범위")]
        [SerializeField] private float searchRange = 8f;

        private void Awake()
        {
            DOTween.SetTweensCapacity(500, 50);
        }

        private void Start()
        {
            // Init() 호출을 SetTarget으로 이동하여 player 참조가 보장되도록 합니다.
        }

        private void Init()
        {
            if (player != null)
            {
                player_Weaphon = player.WeaphonBase;
                if (player_Weaphon != null)
                {
                    _isHitByShoot = player_Weaphon.isShooting;
                }
            }

            Mob_Hp = initialHp;
            Mob_Speed = initialSpeed;
            Mob_AttackDamage = initialAttackDamage;
            Mob_AttackSpeed = initialAttackSpeed;
            Mob_AttackRange = initialAttackRange;
            Mob_StunTime = initialStunTime;

            Mob_IsDie = false;
            Mob_IsHit = false;
        }

        public override void SetTarget(PlayerBase target)
        {
            base.SetTarget(target);
            Init();
        }

        public override void OnEnable()
        {
            base.OnEnable();
            MoveInsideMapIfOutside(); // 스폰 시 맵 밖이면 맵 안으로 이동
            SetMobState(MobState.Move);
        }


        private void FixedUpdate()
        {

            // todo 스폰시 맵 밖이면 맵 안까지 이동

            // 플레이어 탐색 범위 내에 있을 때만 추적 및 공격
            if (!ismove || player == null)
            {
                if (ismove) transform.DOKill();
                return;
            }
            float distanceToPlayer = Vector3.Distance(transform.position, player.transform.position);
            if (distanceToPlayer > searchRange)
            {
                // 플레이어가 탐색 범위 밖에 있으면 추적하지 않음
                return;
            }
            // 플레이어를 추적하는 로직
            Vector3 direction = (player.transform.position - transform.position).normalized;
            transform.position += direction * Mob_Speed * Time.fixedDeltaTime;

            // 플레이어 방향으로 몹 회전 (좌우 반전)
            if (direction.x != 0)
            {
                // direction.x > 0 이면 오른쪽을 보도록 180도 회전 (스프라이트가 왼쪽을 보고 있을 경우)
                // direction.x < 0 이면 왼쪽을 보도록 0도 회전
                float yRotation = direction.x > 0 ? 180f : 0f;
                transform.rotation = Quaternion.Euler(0, yRotation, 0);
            }
        }

        private void OnCollisionEnter2D(Collision2D other)
        {
            if (_isHitByShoot)
            {
                HandleCollision(other);
            }
        }

        private void OnCollisionStay2D(Collision2D other)
        {
            if (!_isHitByShoot)
            {
                HandleCollision(other);
            }
        }

        private void HandleCollision(Collision2D other)
        {
            if (!Mob_IsHit && other.gameObject.CompareTag("Player_Attack"))
            {
                HitCooltime(other).Forget();
                LogManager.Log("_isHitByShoot: "+_isHitByShoot,LogManager.LogCategory.NormalMob);
            }
        }

        private async UniTask HitCooltime(Collision2D other)
        {
            Mob_IsHit = true;

            float attackPower = player_Weaphon.attackPower;
            float stunTime = player_Weaphon.mobStunTime;

            await UniTask.Yield();
            Mob_Hp -= attackPower;

            if (Mob_Hp <= 0)
            {
                SetMobState(MobState.Die);
            }
            else
            {
                Mob_StunTime = stunTime;
                SetMobState(MobState.Stun);
            }

            Mob_IsHit = false;
        }

        protected override void Mob_Idle()
        {
            LogManager.Log("Idle", LogManager.LogCategory.NormalMob);
        }

        protected override void Mob_Move()
        {
            ismove = true;
        }

        protected override void Mob_Stun()
        {
            LogManager.Log("Stun", LogManager.LogCategory.NormalMob);
            ismove = false;
            DOVirtual.DelayedCall(Mob_StunTime, () => { SetMobState(MobState.Move); });
        }

        protected override void Mob_hit()
        {
            base.Mob_hit();
        }

        protected override void Mob_Attack()
        {
            LogManager.Log("Attack", LogManager.LogCategory.NormalMob);
        }

        protected override void Mob_Die()
        {
            base.Mob_Die();
            transform.DOKill();
            LogManager.Log("Die", LogManager.LogCategory.NormalMob);
        }

        private void MoveInsideMapIfOutside()
        {
            // 맵 오브젝트를 "Map" 태그로 찾고, SpriteRenderer의 bounds를 사용
            var mapObj = GameObject.FindGameObjectWithTag("Map");
            if (mapObj == null) return;
            var mapRenderer = mapObj.GetComponent<SpriteRenderer>();
            if (mapRenderer == null) return;
            var bounds = mapRenderer.bounds;
            Vector3 pos = transform.position;
            // x, y 좌표를 맵 영역 내로 클램프
            pos.x = Mathf.Clamp(pos.x, bounds.min.x, bounds.max.x);
            pos.y = Mathf.Clamp(pos.y, bounds.min.y, bounds.max.y);
            transform.position = pos;
        }
    }
}

using System;
using System.Threading;
using Cysharp.Threading.Tasks;
using UnityEngine;

namespace DogGuns_Games.vamsir
{
    /// <summary>
    /// 플레이어 캐릭터의 기본 동작과 속성을 정의하는 기본 클래스
    /// </summary>
    public class PlayerBase : MonoBehaviour
    {
        #region 플레이어 스탯

        [Header("공격 관련 스탯")]
        public float AttackPower { get; set; }
        public float CoolTime { get; set; }
        public float AttackSpeed { get; set; }
        public float WeaponSize { get; set; }
        public float ProjectileCount { get; set; }
        public float CriticalChance { get; set; }
        public float CriticalDamage { get; set; }

        [Header("방어 및 생존 관련 스탯")]
        public float Health { get; set; }
        public float HealthRegen { get; set; }
        public float Defense { get; set; }
        public float MoveSpeed { get; set; }

        [Header("자원 획득 관련 스탯")]
        public float ExpGain { get; set; }
        public float GoldGain { get; set; }
        public float ItemGainRange { get; set; }
        public float Reroll { get; set; }

        [Header("캐릭터 정보")]
        public float Level { get; set; } = 0f;
        public Vector3 AttackAngle { get; set; }
        public int characterIndex; // 현재 캐릭터 인덱스

        [Header("경험치 시스템")]
        public float CurrentExp { get; set; } = 0f;
        public float MaxExp { get; set; } = 100f;
        [SerializeField]
        private GameObject _playerObjectParent;

        // 레벨업 이벤트
        public static event Action<float> OnLevelUp;
        public static event Action<float, float> OnExpChanged; // currentExp, maxExp

        #endregion

        #region 플레이어 상태 관리

        /// <summary>
        /// 플레이어의 상태를 정의하는 열거형
        /// </summary>
        public enum PlayerState
        {
            Idle,
            Move,
            Hit,
            Attack
        }

        private PlayerState _playState;
        public bool ishit = false;
        public Weaphon_base WeaphonBase { get; set; }

        /// <summary>
        /// 플레이어 상태 프로퍼티 - 상태 변경시 SetPlayerState 메서드 호출
        /// </summary>
        public PlayerState PlayState
        {
            get => _playState;
            set
            {
                _playState = value;
                SetPlayerState(_playState);
            }
        }

        /// <summary>
        /// 플레이어의 상태에 따른 동작 분기 처리
        /// </summary>
        private void SetPlayerState(PlayerState state)
        {
            switch (state)
            {
                case PlayerState.Idle:
                    Player_Idle();
                    break;
                case PlayerState.Move:
                    PlayerMovement();
                    break;
                case PlayerState.Hit:
                    Player_Hit();
                    break;
                case PlayerState.Attack:
                    Player_attack(AttackAngle);
                    break;
            }
        }

        #endregion

        #region 초기화

        /// <summary>
        /// 오브젝트가 활성화될 때 호출되는 메서드
        /// </summary>
        public virtual void OnEnable()
        {
        //    InitializeWeapon();
            Level = 0f;
            PlayStateManager.OnGameOver += OnGameOver;
            _playerObjectParent = transform.parent != null ? transform.parent.gameObject : gameObject;
            // "Map" 태그가 붙은 오브젝트에서 SpriteRenderer를 찾아서 맵 범위로 설정
            SetMapRange(GameObject.FindGameObjectWithTag("Map").GetComponent<SpriteRenderer>());  }

        protected virtual void OnDisable()
        {
            PlayStateManager.OnGameOver -= OnGameOver;
        }

        private void OnGameOver()
        {
            // 플레이어 이동 정지: 상태를 Idle로 변경하거나, 이동 관련 변수/컨트롤러 비활성화
            PlayState = PlayerState.Idle;
            // 필요시 이동 관련 추가 변수/컨트롤러도 비활성화
        }

        /// <summary>
        /// 무기 초기화 및 위치 설정
        /// </summary>
        public void InitializeWeapon(Weaphon_base weapon)
        {
            if (weapon != null)
            {
                WeaphonBase = weapon;
                WeaphonBase.transform.SetParent(transform);
                WeaphonBase.transform.localPosition = Vector3.zero;
            }
            else
            {
                Debug.LogWarning("전달된 무기 베이스가 없습니다.");
            }
        }

        #endregion

        #region 충돌 처리

        /// <summary>
        /// 플레이어와 다른 오브젝트 간의 충돌 처리
        /// </summary>
        public virtual void OnCollisionStay2D(Collision2D other)
        {
            GameObject colliderObject = other.gameObject;
            string objectTag = colliderObject.tag;

            switch (objectTag)
            {
                case "Mob":
                    HandleMobCollision(colliderObject);
                    break;
                case "Exp":
                    HandleExpCollision(colliderObject);
                    break;
                case "Coin":
                    HandleCoinCollision(colliderObject);
                    break;
            }
        }

        /// <summary>
        /// 몹과의 충돌 처리 및 피해 계산
        /// </summary>
        /// <param name="mobObject">충돌한 몹 게임오브젝트</param>
        private void HandleMobCollision(GameObject mobObject)
        {
            // 이미 피격 상태면 추가 처리 없음
            if (ishit) return;

            // 피격 상태 설정
            ishit = true;

            // 무적 시간 후 피격 상태 해제 (캔슬레이션 토큰 추가)
            CancellationTokenSource cts = new CancellationTokenSource();
            DelayAction(1f, () => ishit = false, cts.Token).Forget();

            // 피격 상태로 변경
            PlayState = PlayerState.Hit;

            // 몹으로부터 피해 계산
            VamserMobBase mob = mobObject.GetComponent<VamserMobBase>();
            if (mob != null)
            {
                float damageAmount = CalculateDamage(mob.Mob_AttackDamage);
                ApplyDamage(damageAmount);
            }
        }

        /// <summary>
        /// 방어력을 고려한 최종 피해량 계산
        /// </summary>
        private float CalculateDamage(float rawDamage)
        {
            // 방어력 공식 적용 (방어력이 높을수록 피해 감소)
            return Mathf.Max(1, rawDamage * (100 / (100 + Defense)));
        }

        /// <summary>
        /// 플레이어에게 피해 적용 및 효과 처리
        /// </summary>
        private void ApplyDamage(float damageAmount)
        {
            Health -= damageAmount;

            // 피해량 디버그 로그
            LogManager.Log($"플레이어가 <color=#FF0000>{damageAmount:F1}</color> 데미지를 받음 (남은 체력: {Health:F1})", LogManager.LogCategory.PlayerBase);


            // 피격 효과 재생
            PlayHitEffect();
        }

        /// <summary>
        /// 경험치 아이템과의 충돌 처리
        /// </summary>
        private void HandleExpCollision(GameObject expObject)
        {
            EXP_Obj expObj = expObject.GetComponent<EXP_Obj>();
            if (expObj != null && expObj.objectPoolSpawner != null)
            {
                // 경험치 획득 처리 추가
                float expAmount = 1 * ExpGain; // 기본 경험치에 획득 보너스 적용
                LogManager.Log($"경험치 {expAmount} 획득", LogManager.LogCategory.PlayerBase);
                // 경험치 증가 및 UI 업데이트
                AddExperience(expAmount);
                // 오브젝트 풀로 반환
                expObj.objectPoolSpawner.ExpObjectPool.Release(expObj);
            }
        }

        /// <summary>
        /// 코인 아이템과의 충돌 처리
        /// </summary>
        private void HandleCoinCollision(GameObject coinObject)
        {
            Coin_Obj coinObj = coinObject.GetComponent<Coin_Obj>();
            if (coinObj != null && coinObj.objectPoolSpawner != null)
            {
                // 코인 획득량에 골드 획득 보너스 적용 가능
                float goldBonus = GoldGain > 0 ? GoldGain : 1;
                int coinsToAdd = Mathf.RoundToInt(1 * goldBonus);
                // 실제 코인 증가
                PlayerDataManagerDontdesytoy.Instance.scritpableobjPlayerData.ingameCoin += coinsToAdd;
                LogManager.Log($"코인 {coinsToAdd}개 획득", LogManager.LogCategory.PlayerBase);
                // 오브젝트 풀로 반환
                coinObj.objectPoolSpawner.CoinObjectPool.Release(coinObj);
            }
        }

        #endregion

        #region 플레이어 액션

        /// <summary>
        /// 플레이어 공격 동작
        /// </summary>
        public virtual void Player_attack(Vector3 attackAngle)
        {
            attackAngle = this.AttackAngle;
            // 자식 클래스에서 구현
        }

        /// <summary>
        /// 플레이어 사망 처리
        /// </summary>
        public virtual void Player_Die()
        {
            LogManager.Log("플레이어 사망 - 게임 오버 처리 시작", LogManager.LogCategory.PlayerBase);
            // 게임 오버 상태로 변경
            if (PlayStateManager.instance != null)
            {
                PlayStateManager.instance.PlayState = PlayStateManager.GameState.GameOver;
            }
            // 플레이어 비활성화 (선택사항)
            gameObject.SetActive(false);
        }

        /// <summary>
        /// 플레이어 피격 동작
        /// </summary>
        public virtual void Player_Hit()
        {
            // 체력이 0 이하로 떨어지면 사망 처리
            if (Health <= 0)
            {
                Player_Die();
            }
        }

        /// <summary>
        /// 피격 효과 재생
        /// </summary>
        protected virtual void PlayHitEffect()
        {
            // 애니메이션 효과, 사운드 효과 등 구현
            // AudioManager.Instance.PlaySound("PlayerHit");
            LogManager.Log("피격 효과 재생", LogManager.LogCategory.PlayerBase);
        }

        /// <summary>
        /// 플레이어 대기 동작
        /// </summary>
        public virtual void Player_Idle()
        {
            // 자식 클래스에서 구현
        }

        /// <summary>
        /// 플레이어 이동 동작
        /// </summary>
        public virtual void PlayerMovement()
        {
            // 자식 클래스에서 구현
        }

        #endregion

        #region 경험치 시스템

        /// <summary>
        /// 경험치를 추가하고 레벨업을 체크합니다.
        /// </summary>
        /// <param name="expAmount">추가할 경험치 양</param>
        public void AddExperience(float expAmount)
        {
            CurrentExp += expAmount;

            // 경험치 변경 이벤트 발생
            OnExpChanged?.Invoke(CurrentExp, MaxExp);

            // 레벨업 체크
            CheckLevelUp();
        }

        /// <summary>
        /// 레벨업 조건을 체크하고 레벨업을 처리합니다.
        /// </summary>
        private void CheckLevelUp()
        {
            while (CurrentExp >= MaxExp)
            {
                // 경험치 차감
                CurrentExp -= MaxExp;
                // 레벨 증가
                Level++;
                // 다음 레벨 필요 경험치 계산
                MaxExp = CalculateMaxExpForLevel(Level);
                // 레벨업 이벤트 발생
                OnLevelUp?.Invoke(Level);
                // 레벨업 효과 처리
                HandleLevelUp();
                LogManager.Log($"레벨업! 현재 레벨: {Level}, 필요 경험치: {MaxExp}", LogManager.LogCategory.PlayerBase);
                // 경험치 변경 이벤트를 레벨업마다 호출하여 UI가 즉시 반영되도록 함
                OnExpChanged?.Invoke(CurrentExp, MaxExp);
            }
            // 경험치 변경 이벤트 재발생 (레벨업 후 UI 업데이트용)
            OnExpChanged?.Invoke(CurrentExp, MaxExp);
        }

        /// <summary>
        /// 레벨에 따른 최대 경험치를 계산합니다.
        /// </summary>
        /// <param name="level">현재 레벨</param>
        /// <returns>해당 레벨에서 필요한 최대 경험치</returns>
        private float CalculateMaxExpForLevel(float level)
        {
            // 레벨 0→1: 10, 레벨 1→2: 20, ...
            return (level + 1) * 10f;
        }

        /// <summary>
        /// 레벨업 시 플레이어 능력치 증가를 처리합니다.
        /// </summary>
        private void HandleLevelUp()
        {
            // 레벨업 시 스탯 증가
            AttackPower += 5f;
            Health += 20f;
            Defense += 2f;
            MoveSpeed += 0.1f;

            // 레벨업 사운드 효과 (선택사항)
            // SoundManager.PlaySound(Sound.SFX, "LevelUp");
        }

        /// <summary>
        /// 현재 경험치 진행률을 0~1 범위로 반환합니다.
        /// </summary>
        /// <returns>경험치 진행률 (0~1)</returns>
        public float GetExpProgress()
        {
            return MaxExp > 0 ? CurrentExp / MaxExp : 0f;
        }

        #endregion

        #region 유틸리티 메서드

        /// <summary>
        /// 지정된 시간 후에 액션을 실행합니다.
        /// </summary>
        /// <param name="delay">지연 시간(초)</param>
        /// <param name="action">실행할 액션</param>
        /// <param name="cancellationToken">취소 토큰(선택 사항)</param>
        /// <returns>UniTask</returns>
        public UniTask DelayAction(float delay, Action action, CancellationToken cancellationToken = default)
        {
            return UniTask.Delay(
                TimeSpan.FromSeconds(delay), 
                cancellationToken: cancellationToken
            ).ContinueWith(() => {
                if (!cancellationToken.IsCancellationRequested)
                {
                    action?.Invoke();
                }
            });
        }

        #endregion

        #region 플레이어 자동 이동 및 공격 로직

        public bool IsAutoMoveAttack = false;
        private CancellationTokenSource autoMoveAttackCTS;
        private Transform currentTarget;
        private float autoAttackTimer = 0f;
        private SpriteRenderer mapRange;

        /// <summary>
        /// 자동 이동/공격 활성화
        /// </summary>
        public void EnableAutoMoveAttack()
        {
            if (IsAutoMoveAttack) return;
            IsAutoMoveAttack = true;
            autoMoveAttackCTS = new CancellationTokenSource();
            AutoMoveAttackLoop(autoMoveAttackCTS.Token).Forget();
        }

        /// <summary>
        /// 자동 이동/공격 비활성화
        /// </summary>
        public void DisableAutoMoveAttack()
        {
            IsAutoMoveAttack = false;
            autoMoveAttackCTS?.Cancel();
            currentTarget = null;
        }

        /// <summary>
        /// 맵 범위 설정
        /// </summary>
        /// <param name="map">설정할 맵 범위 스프라이트 렌더러</param>
        public void SetMapRange(SpriteRenderer map)
        {
            mapRange = map;
        }

        private async UniTaskVoid AutoMoveAttackLoop(CancellationToken token)
        {
            while (IsAutoMoveAttack && !token.IsCancellationRequested)
            {
                currentTarget = FindClosestEnemy();
                if (currentTarget != null && mapRange != null && _playerObjectParent != null)
                {
                    Vector3 dir = (currentTarget.position - _playerObjectParent.transform.position).normalized;
                    float distance = Vector3.Distance(_playerObjectParent.transform.position, currentTarget.position);
                    bool isRanged = WeaphonBase != null && WeaphonBase.isShooting;
                    float stopDistance = isRanged ? 2.5f : 0.5f;
                    float deltaSpeed = MoveSpeed * Time.deltaTime;
                    Debug.Log($"[AutoMoveAttack] distance: {distance}, stopDistance: {stopDistance}, deltaSpeed: {deltaSpeed}, MoveSpeed: {MoveSpeed}");
                    Debug.Log($"[AutoMoveAttack] mapRange: {(mapRange != null ? mapRange.name : "null")}, _playerObjectParent: {_playerObjectParent.name}");
                    // 이동: 무기 타입에 따라 멈추는 거리 다름, 항상 MoveSpeed 적용
                    if (distance > stopDistance)
                    {
                        Vector3 rawTargetPosition = _playerObjectParent.transform.position + dir * deltaSpeed;
                        Bounds mapBounds = mapRange.bounds;
                        Vector3 clampedPosition = new Vector3(
                            Mathf.Clamp(rawTargetPosition.x, mapBounds.min.x, mapBounds.max.x),
                            Mathf.Clamp(rawTargetPosition.y, mapBounds.min.y, mapBounds.max.y),
                            rawTargetPosition.z
                        );
                        Debug.Log($"[AutoMoveAttack] Move to: {clampedPosition}");
                        _playerObjectParent.transform.position = clampedPosition;
                    }
                    // 공격: 멈추는 거리 이내일 때만 공격
                    if (distance <= stopDistance)
                    {
                        autoAttackTimer += Time.deltaTime;
                        if (autoAttackTimer >= CoolTime)
                        {
                            autoAttackTimer = 0f;
                            AttackAngle = dir;
                            PlayState = PlayerState.Attack;
                        }
                    }
                    // 타겟이 사라졌거나 처치되었는지 체크
                    if (!currentTarget.gameObject.activeInHierarchy)
                    {
                        currentTarget = null;
                    }
                }
                else
                {
                    Debug.Log($"[AutoMoveAttack] 조건 불충분: currentTarget={currentTarget}, mapRange={mapRange}, _playerObjectParent={_playerObjectParent}");
                }
                await UniTask.Yield(PlayerLoopTiming.Update);
            }
        }

        /// <summary>
        /// 맵 내에서 가장 가까운 적을 탐색
        /// </summary>
        private Transform FindClosestEnemy()
        {
            GameObject[] enemies = GameObject.FindGameObjectsWithTag("Mob");
            Transform closest = null;
            float minDist = float.MaxValue;
            foreach (var enemy in enemies)
            {
                float dist = Vector3.Distance(transform.position, enemy.transform.position);
                if (dist < minDist)
                {
                    minDist = dist;
                    closest = enemy.transform;
                }
            }
            return closest;
        }

        #endregion

    }
}

using System;
using System.Threading;
using Cysharp.Threading.Tasks;
using UnityEngine;

namespace DogGuns_Games.vamsir
{
    /// <summary>
    /// 플레이어 캐릭터의 기본 동작과 속성을 정의하는 기본 클래스
    /// </summary>
    public class PlayerBase : MonoBehaviour
    {
        #region 플레이어 스탯

        [Header("공격 관련 스탯")]
        public float AttackPower { get; set; }
        public float CoolTime { get; set; }
        public float AttackSpeed { get; set; }
        public float WeaponSize { get; set; }
        public float ProjectileCount { get; set; }
        public float CriticalChance { get; set; }
        public float CriticalDamage { get; set; }

        [Header("방어 및 생존 관련 스탯")]
        public float Health { get; set; }
        public float HealthRegen { get; set; }
        public float Defense { get; set; }
        public float MoveSpeed { get; set; }

        [Header("자원 획득 관련 스탯")]
        public float ExpGain { get; set; }
        public float GoldGain { get; set; }
        public float ItemGainRange { get; set; }
        public float Reroll { get; set; }

        [Header("캐릭터 정보")]
        public float Level { get; set; } = 0f;
        public Vector3 AttackAngle { get; set; }
        public int characterIndex; // 현재 캐릭터 인덱스

        [Header("경험치 시스템")]
        public float CurrentExp { get; set; } = 0f;
        public float MaxExp { get; set; } = 100f;
        [SerializeField]
        private GameObject _playerObjectParent;

        // 레벨업 이벤트
        public static event Action<float> OnLevelUp;
        public static event Action<float, float> OnExpChanged; // currentExp, maxExp

        #endregion

        #region 플레이어 상태 관리

        /// <summary>
        /// 플레이어의 상태를 정의하는 열거형
        /// </summary>
        public enum PlayerState
        {
            Idle,
            Move,
            Hit,
            Attack
        }

        private PlayerState _playState;
        public bool ishit = false;
        public Weaphon_base WeaphonBase { get; set; }

        /// <summary>
        /// 플레이어 상태 프로퍼티 - 상태 변경시 SetPlayerState 메서드 호출
        /// </summary>
        public PlayerState PlayState
        {
            get => _playState;
            set
            {
                _playState = value;
                SetPlayerState(_playState);
            }
        }

        /// <summary>
        /// 플레이어의 상태에 따른 동작 분기 처리
        /// </summary>
        private void SetPlayerState(PlayerState state)
        {
            switch (state)
            {
                case PlayerState.Idle:
                    Player_Idle();
                    break;
                case PlayerState.Move:
                    PlayerMovement();
                    break;
                case PlayerState.Hit:
                    Player_Hit();
                    break;
                case PlayerState.Attack:
                    Player_attack(AttackAngle);
                    break;
            }
        }

        #endregion

        #region 초기화

        /// <summary>
        /// 오브젝트가 활성화될 때 호출되는 메서드
        /// </summary>
        public virtual void OnEnable()
        {
        //    InitializeWeapon();
            Level = 0f;
            PlayStateManager.OnGameOver += OnGameOver;
            _playerObjectParent = transform.parent != null ? transform.parent.gameObject : gameObject;
            // "Map" 태그가 붙은 오브젝트에서 SpriteRenderer를 찾아서 맵 범위로 설정
            SetMapRange(GameObject.FindGameObjectWithTag("Map").GetComponent<SpriteRenderer>());  }

        protected virtual void OnDisable()
        {
            PlayStateManager.OnGameOver -= OnGameOver;
        }

        private void OnGameOver()
        {
            // 플레이어 이동 정지: 상태를 Idle로 변경하거나, 이동 관련 변수/컨트롤러 비활성화
            PlayState = PlayerState.Idle;
            // 필요시 이동 관련 추가 변수/컨트롤러도 비활성화
        }

        /// <summary>
        /// 무기 초기화 및 위치 설정
        /// </summary>
        public void InitializeWeapon(Weaphon_base weapon)
        {
            if (weapon != null)
            {
                WeaphonBase = weapon;
                WeaphonBase.transform.SetParent(transform);
                WeaphonBase.transform.localPosition = Vector3.zero;
            }
            else
            {
                Debug.LogWarning("전달된 무기 베이스가 없습니다.");
            }
        }

        #endregion

        #region 충돌 처리

        /// <summary>
        /// 플레이어와 다른 오브젝트 간의 충돌 처리
        /// </summary>
        public virtual void OnCollisionStay2D(Collision2D other)
        {
            GameObject colliderObject = other.gameObject;
            string objectTag = colliderObject.tag;

            switch (objectTag)
            {
                case "Mob":
                    HandleMobCollision(colliderObject);
                    break;
                case "Exp":
                    HandleExpCollision(colliderObject);
                    break;
                case "Coin":
                    HandleCoinCollision(colliderObject);
                    break;
            }
        }

        /// <summary>
        /// 몹과의 충돌 처리 및 피해 계산
        /// </summary>
        /// <param name="mobObject">충돌한 몹 게임오브젝트</param>
        private void HandleMobCollision(GameObject mobObject)
        {
            // 이미 피격 상태면 추가 처리 없음
            if (ishit) return;

            // 피격 상태 설정
            ishit = true;

            // 무적 시간 후 피격 상태 해제 (캔슬레이션 토큰 추가)
            CancellationTokenSource cts = new CancellationTokenSource();
            DelayAction(1f, () => ishit = false, cts.Token).Forget();

            // 피격 상태로 변경
            PlayState = PlayerState.Hit;

            // 몹으로부터 피해 계산
            VamserMobBase mob = mobObject.GetComponent<VamserMobBase>();
            if (mob != null)
            {
                float damageAmount = CalculateDamage(mob.Mob_AttackDamage);
                ApplyDamage(damageAmount);
            }
        }

        /// <summary>
        /// 방어력을 고려한 최종 피해량 계산
        /// </summary>
        private float CalculateDamage(float rawDamage)
        {
            // 방어력 공식 적용 (방어력이 높을수록 피해 감소)
            return Mathf.Max(1, rawDamage * (100 / (100 + Defense)));
        }

        /// <summary>
        /// 플레이어에게 피해 적용 및 효과 처리
        /// </summary>
        private void ApplyDamage(float damageAmount)
        {
            Health -= damageAmount;

            // 피해량 디버그 로그
            LogManager.Log($"플레이어가 <color=#FF0000>{damageAmount:F1}</color> 데미지를 받음 (남은 체력: {Health:F1})", LogManager.LogCategory.PlayerBase);


            // 피격 효과 재생
            PlayHitEffect();
        }

        /// <summary>
        /// 경험치 아이템과의 충돌 처리
        /// </summary>
        private void HandleExpCollision(GameObject expObject)
        {
            EXP_Obj expObj = expObject.GetComponent<EXP_Obj>();
            if (expObj != null && expObj.objectPoolSpawner != null)
            {
                // 경험치 획득 처리 추가
                float expAmount = 1 * ExpGain; // 기본 경험치에 획득 보너스 적용
                LogManager.Log($"경험치 {expAmount} 획득", LogManager.LogCategory.PlayerBase);
                // 경험치 증가 및 UI 업데이트
                AddExperience(expAmount);
                // 오브젝트 풀로 반환
                expObj.objectPoolSpawner.ExpObjectPool.Release(expObj);
            }
        }

        /// <summary>
        /// 코인 아이템과의 충돌 처리
        /// </summary>
        private void HandleCoinCollision(GameObject coinObject)
        {
            Coin_Obj coinObj = coinObject.GetComponent<Coin_Obj>();
            if (coinObj != null && coinObj.objectPoolSpawner != null)
            {
                // 코인 획득량에 골드 획득 보너스 적용 가능
                float goldBonus = GoldGain > 0 ? GoldGain : 1;
                int coinsToAdd = Mathf.RoundToInt(1 * goldBonus);
                // 실제 코인 증가
                PlayerDataManagerDontdesytoy.Instance.scritpableobjPlayerData.ingameCoin += coinsToAdd;
                LogManager.Log($"코인 {coinsToAdd}개 획득", LogManager.LogCategory.PlayerBase);
                // 오브젝트 풀로 반환
                coinObj.objectPoolSpawner.CoinObjectPool.Release(coinObj);
            }
        }

        #endregion

        #region 플레이어 액션

        /// <summary>
        /// 플레이어 공격 동작
        /// </summary>
        public virtual void Player_attack(Vector3 attackAngle)
        {
            attackAngle = this.AttackAngle;
            // 자식 클래스에서 구현
        }

        /// <summary>
        /// 플레이어 사망 처리
        /// </summary>
        public virtual void Player_Die()
        {
            LogManager.Log("플레이어 사망 - 게임 오버 처리 시작", LogManager.LogCategory.PlayerBase);
            // 게임 오버 상태로 변경
            if (PlayStateManager.instance != null)
            {
                PlayStateManager.instance.PlayState = PlayStateManager.GameState.GameOver;
            }
            // 플레이어 비활성화 (선택사항)
            gameObject.SetActive(false);
        }

        /// <summary>
        /// 플레이어 피격 동작
        /// </summary>
        public virtual void Player_Hit()
        {
            // 체력이 0 이하로 떨어지면 사망 처리
            if (Health <= 0)
            {
                Player_Die();
            }
        }

        /// <summary>
        /// 피격 효과 재생
        /// </summary>
        protected virtual void PlayHitEffect()
        {
            // 애니메이션 효과, 사운드 효과 등 구현
            // AudioManager.Instance.PlaySound("PlayerHit");
            LogManager.Log("피격 효과 재생", LogManager.LogCategory.PlayerBase);
        }

        /// <summary>
        /// 플레이어 대기 동작
        /// </summary>
        public virtual void Player_Idle()
        {
            // 자식 클래스에서 구현
        }

        /// <summary>
        /// 플레이어 이동 동작
        /// </summary>
        public virtual void PlayerMovement()
        {
            // 자식 클래스에서 구현
        }

        #endregion

        #region 경험치 시스템

        /// <summary>
        /// 경험치를 추가하고 레벨업을 체크합니다.
        /// </summary>
        /// <param name="expAmount">추가할 경험치 양</param>
        public void AddExperience(float expAmount)
        {
            CurrentExp += expAmount;

            // 경험치 변경 이벤트 발생
            OnExpChanged?.Invoke(CurrentExp, MaxExp);

            // 레벨업 체크
            CheckLevelUp();
        }

        /// <summary>
        /// 레벨업 조건을 체크하고 레벨업을 처리합니다.
        /// </summary>
        private void CheckLevelUp()
        {
            while (CurrentExp >= MaxExp)
            {
                // 경험치 차감
                CurrentExp -= MaxExp;
                // 레벨 증가
                Level++;
                // 다음 레벨 필요 경험치 계산
                MaxExp = CalculateMaxExpForLevel(Level);
                // 레벨업 이벤트 발생
                OnLevelUp?.Invoke(Level);
                // 레벨업 효과 처리
                HandleLevelUp();
                LogManager.Log($"레벨업! 현재 레벨: {Level}, 필요 경험치: {MaxExp}", LogManager.LogCategory.PlayerBase);
                // 경험치 변경 이벤트를 레벨업마다 호출하여 UI가 즉시 반영되도록 함
                OnExpChanged?.Invoke(CurrentExp, MaxExp);
            }
            // 경험치 변경 이벤트 재발생 (레벨업 후 UI 업데이트용)
            OnExpChanged?.Invoke(CurrentExp, MaxExp);
        }

        /// <summary>
        /// 레벨에 따른 최대 경험치를 계산합니다.
        /// </summary>
        /// <param name="level">현재 레벨</param>
        /// <returns>해당 레벨에서 필요한 최대 경험치</returns>
        private float CalculateMaxExpForLevel(float level)
        {
            // 레벨 0→1: 10, 레벨 1→2: 20, ...
            return (level + 1) * 10f;
        }

        /// <summary>
        /// 레벨업 시 플레이어 능력치 증가를 처리합니다.
        /// </summary>
        private void HandleLevelUp()
        {
            // 레벨업 시 스탯 증가
            AttackPower += 5f;
            Health += 20f;
            Defense += 2f;
            MoveSpeed += 0.1f;

            // 레벨업 사운드 효과 (선택사항)
            // SoundManager.PlaySound(Sound.SFX, "LevelUp");
        }

        /// <summary>
        /// 현재 경험치 진행률을 0~1 범위로 반환합니다.
        /// </summary>
        /// <returns>경험치 진행률 (0~1)</returns>
        public float GetExpProgress()
        {
            return MaxExp > 0 ? CurrentExp / MaxExp : 0f;
        }

        #endregion

        #region 유틸리티 메서드

        /// <summary>
        /// 지정된 시간 후에 액션을 실행합니다.
        /// </summary>
        /// <param name="delay">지연 시간(초)</param>
        /// <param name="action">실행할 액션</param>
        /// <param name="cancellationToken">취소 토큰(선택 사항)</param>
        /// <returns>UniTask</returns>
        public UniTask DelayAction(float delay, Action action, CancellationToken cancellationToken = default)
        {
            return UniTask.Delay(
                TimeSpan.FromSeconds(delay), 
                cancellationToken: cancellationToken
            ).ContinueWith(() => {
                if (!cancellationToken.IsCancellationRequested)
                {
                    action?.Invoke();
                }
            });
        }

        #endregion

        #region 플레이어 자동 이동 및 공격 로직

        public bool IsAutoMoveAttack = false;
        private CancellationTokenSource autoMoveAttackCTS;
        private Transform currentTarget;
        private float autoAttackTimer = 0f;
        private SpriteRenderer mapRange;

        /// <summary>
        /// 자동 이동/공격 활성화
        /// </summary>
        public void EnableAutoMoveAttack()
        {
            if (IsAutoMoveAttack) return;
            IsAutoMoveAttack = true;
            autoMoveAttackCTS = new CancellationTokenSource();
            AutoMoveAttackLoop(autoMoveAttackCTS.Token).Forget();
        }

        /// <summary>
        /// 자동 이동/공격 비활성화
        /// </summary>
        public void DisableAutoMoveAttack()
        {
            IsAutoMoveAttack = false;
            autoMoveAttackCTS?.Cancel();
            currentTarget = null;
        }

        /// <summary>
        /// 맵 범위 설정
        /// </summary>
        /// <param name="map">설정할 맵 범위 스프라이트 렌더러</param>
        public void SetMapRange(SpriteRenderer map)
        {
            mapRange = map;
        }

        private async UniTaskVoid AutoMoveAttackLoop(CancellationToken token)
        {
            while (IsAutoMoveAttack && !token.IsCancellationRequested)
            {
                currentTarget = FindClosestEnemy();
                if (currentTarget != null && mapRange != null && _playerObjectParent != null)
                {
                    Vector3 dir = (currentTarget.position - _playerObjectParent.transform.position).normalized;
                    float distance = Vector3.Distance(_playerObjectParent.transform.position, currentTarget.position);
                    bool isRanged = WeaphonBase != null && WeaphonBase.isShooting;
                    float stopDistance = isRanged ? 2.5f : 0.5f;
                    float deltaSpeed = MoveSpeed * Time.deltaTime;
                    Debug.Log($"[AutoMoveAttack] distance: {distance}, stopDistance: {stopDistance}, deltaSpeed: {deltaSpeed}, MoveSpeed: {MoveSpeed}");
                    Debug.Log($"[AutoMoveAttack] mapRange: {(mapRange != null ? mapRange.name : "null")}, _playerObjectParent: {_playerObjectParent.name}");
                    // 이동: 무기 타입에 따라 멈추는 거리 다름, 항상 MoveSpeed 적용
                    if (distance > stopDistance)
                    {
                        Vector3 rawTargetPosition = _playerObjectParent.transform.position + dir * deltaSpeed;
                        Bounds mapBounds = mapRange.bounds;
                        Vector3 clampedPosition = new Vector3(
                            Mathf.Clamp(rawTargetPosition.x, mapBounds.min.x, mapBounds.max.x),
                            Mathf.Clamp(rawTargetPosition.y, mapBounds.min.y, mapBounds.max.y),
                            rawTargetPosition.z
                        );
                        Debug.Log($"[AutoMoveAttack] Move to: {clampedPosition}");
                        _playerObjectParent.transform.position = clampedPosition;
                    }
                    // 공격: 멈추는 거리 이내일 때만 공격
                    if (distance <= stopDistance)
                    {
                        autoAttackTimer += Time.deltaTime;
                        if (autoAttackTimer >= CoolTime)
                        {
                            autoAttackTimer = 0f;
                            AttackAngle = dir;
                            PlayState = PlayerState.Attack;
                        }
                    }
                    // 타겟이 사라졌거나 처치되었는지 체크
                    if (!currentTarget.gameObject.activeInHierarchy)
                    {
                        currentTarget = null;
                    }
                }
                else
                {
                    Debug.Log($"[AutoMoveAttack] 조건 불충분: currentTarget={currentTarget}, mapRange={mapRange}, _playerObjectParent={_playerObjectParent}");
                }
                await UniTask.Yield(PlayerLoopTiming.Update);
            }
        }

        /// <summary>
        /// 맵 내에서 가장 가까운 적을 탐색
        /// </summary>
        private Transform FindClosestEnemy()
        {
            GameObject[] enemies = GameObject.FindGameObjectsWithTag("Mob");
            Transform closest = null;
            float minDist = float.MaxValue;
            foreach (var enemy in enemies)
            {
                float dist = Vector3.Distance(_playerObjectParent.transform.position, enemy.transform.position);
                if (dist < minDist)
                {
                    minDist = dist;
                    closest = enemy.transform;
                }
            }
            return closest;
        }

        #endregion

    }
}

using System.Threading;
using Cysharp.Threading.Tasks;
using UnityEngine;
using DG.Tweening;
using UnityEngine.UI;

namespace DogGuns_Games.vamsir
{
    public class VamPlayerControll : MonoBehaviour
    {

        //todo 아직 맵안에 들어오지 않은 적은 자동공격에 탐색되지않게 

        #region 필드 및 변수

        [Header("<color=green>Player Object")] [SerializeField]
        private GameObject player;

        [Header("<color=green>Player charactor Object")] [SerializeField]
        private PlayerBase playerCharactor;

        [Header("<color=green>Player HP_IU")] [SerializeField]
        private Slider playerHpSliderPrefab;

        private float _playerHpSliderValue = 0;

        private Animator _playerAnimator;

        [Header("<color=green>Joystick")] [SerializeField]
        private VariableJoystick variableJoystick;

        [Header("<color=green>camera")] [SerializeField]
        private Camera cameraTransform;

        [Header("<color=green>Move Duration")] [SerializeField]
        private float moveDuration = 0.1f;


        private Slider _playerHpSlider; // 인스턴스화된 슬라이더 참조 추가

        [Header("<color=green>Map Range")] [SerializeField]
        private SpriteRenderer mapRange;


        bool _isGameStart = false;

        bool _isAttack = false;

        [Header("<color=green>자동 공격 설정")] 
        [Tooltip("자동 공격 시 플레이어가 멈추는 거리(공격 사거리)")]
        public float autoAttackStopDistance = 1.5f;
        [Tooltip("자동 공격 시 이동 속도 배율")]
        public float autoAttackMoveSpeedMultiplier = 1.0f;

        private bool _isJoystickActive = false;
        private bool _autoAttackEnabledByToggle = true;

        private float joystickInputThreshold = 0.1f;
        private float joystickIdleTime = 0.2f; // 입력이 없을 때 자동공격 재활성화까지 대기 시간
        private float joystickIdleTimer = 0f;
        private bool _autoAttackActive = false;

        private bool _isAutoMoveAttackEnabled = false;


        #endregion

        #region Unity 라이프사이클

        private void Start()
        {
            PlayStateManager.OnGameStart += PlayerInit;
            PlayStateManager.OnGamePause += Pause;
            PlayStateManager.OnGameResume += Resume;
            PlayStateManager.OnGameOver += OnGameOver;
        }

        private void OnDestroy()
        {
            PlayStateManager.OnGameStart -= PlayerInit;
            PlayStateManager.OnGamePause -= Pause;
            PlayStateManager.OnGameResume -= Resume;
            PlayStateManager.OnGameOver -= OnGameOver;
        }

        private void OnGameOver()
        {
            DisableAutoMoveAttack();
            _autoAttackActive = false;
        }

        private void OnJoystickDown()
        {
            _isJoystickActive = true;
            if (_autoAttackEnabledByToggle)
                DisableAutoMoveAttack();
        }

        private void OnJoystickUp()
        {
            _isJoystickActive = false;
            if (_autoAttackEnabledByToggle)
                EnableAutoMoveAttack();
        }

        public void SetAutoAttackToggle(bool isOn)
        {
            _autoAttackEnabledByToggle = isOn;
            if (!isOn && _autoAttackActive)
            {
                DisableAutoMoveAttack();
                _autoAttackActive = false;
            }
            joystickIdleTimer = 0f;
        }

        private void FixedUpdate()
        {
            if (_isGameStart)
            {
                PlayerMovement();
                FallowCamera();
                UpdatePlayerHpSlider();

                // VariableJoystick 수정 없이 입력값 감지
                float inputMagnitude = Mathf.Abs(variableJoystick.Horizontal) + Mathf.Abs(variableJoystick.Vertical);
                if (_autoAttackEnabledByToggle)
                {
                    if (inputMagnitude > joystickInputThreshold)
                    {
                        // 조이스틱 조작 중: 자동공격 비활성화
                        joystickIdleTimer = 0f;
                        if (_autoAttackActive)
                        {
                            DisableAutoMoveAttack();
                            _autoAttackActive = false;
                        }
                    }
                    else
                    {

                        // 조이스틱 입력 없음: 일정 시간 후 자동공격 재활성화
                        joystickIdleTimer += Time.fixedDeltaTime;
                        if (_autoAttackActive && joystickIdleTimer > joystickIdleTime)
                        {
                            EnableAutoMoveAttack();
                        }
                    }
                }
                else
                {
                    if (_autoAttackActive)
                    {
                        DisableAutoMoveAttack();
                        _autoAttackActive = false;
                    }
                }
            }
        }

        #endregion

        #region 게임 상태 관리

        private void PlayerInit()
        {
            // 캐릭터 스폰과의 레이스 컨디션을 피하기 위해 초기화 로직을 AssignCharacter로 이동했습니다.
            // OnGameStart 이벤트에서는 게임 시작 플래그만 설정합니다.
            _isGameStart = true;
        }

        /// <summary>
        /// VamserLikeGameManager가 플레이어 스폰 후 호출하여 캐릭터를 설정합니다.
        /// </summary>
        /// <param name="character">스폰된 플레이어 캐릭터</param>
        public void AssignCharacter(PlayerBase character)
        {
            if (playerCharactor == null && character != null)
            {
                playerCharactor = character;
                playerCharactor.transform.SetParent(player.gameObject.transform);
                _playerAnimator = playerCharactor.GetComponent<Animator>();
                cameraTransform = Camera.main;
                Set_playerHpSlider();
            }
        }

        private void Pause()
        {
            _isGameStart = false;
        }

        private void Resume()
        {
            _isGameStart = true;
        }

        #endregion

        #region UI 설정

        private void Set_playerHpSlider()
        {
            _playerHpSlider = Instantiate(playerHpSliderPrefab, player.transform);
            _playerHpSlider.transform.localPosition = new Vector3(0, -0.4f, 0);
            _playerHpSlider.maxValue = playerCharactor.Health;
            _playerHpSlider.value = playerCharactor.Health;
            _playerHpSliderValue = playerCharactor.Health;
        }

        private void UpdatePlayerHpSlider()
        {
            if (playerCharactor == null)
            {
                PlayerInit();
                return;
            }

            // 현재 체력 값이 이전 값과 다를 때만 슬라이더 업데이트
            if (_playerHpSlider != null && Mathf.Abs(_playerHpSliderValue - playerCharactor.Health) > 0.001f)
            {
                _playerHpSliderValue = playerCharactor.Health;
                _playerHpSlider.value = _playerHpSliderValue;

                // 게임 오버 처리는 PlayerBase의 Player_Hit에서 담당하므로 여기서는 제거
                // PlayerBase에서 Health <= 0일 때 자동으로 게임 오버 처리됨
            }
        }

        #endregion

        #region 플레이어 제어

        /// <summary>
        /// 플레이어 이동을 처리하는 메서드
        /// </summary>
        private void PlayerMovement()
        {
            // 플레이어 객체 유효성 검사
            if (player == null || playerCharactor == null)
            {
                // PlayerInit(); // 재귀 호출 및 로직 문제로 제거
                return;
            }

            // 이동 입력 및 위치 계산
            Vector3 moveDirection = GetJoystickInputDirection();
            Vector3 targetPosition = CalculateTargetPosition(moveDirection);

            // 실제 이동 처리
            MovePlayer(targetPosition);

            // 애니메이션 및 회전 처리
            UpdateAnimationState(moveDirection.magnitude);

            // 공격 처리
            TryAttack(moveDirection);

            // 캐릭터 회전 처리
            UpdateCharacterRotation(moveDirection);
        }

        /// <summary>
        /// 조이스틱 입력을 방향 벡터로 변환
        /// </summary>
        private Vector3 GetJoystickInputDirection()
        {
            return (Vector3.right * variableJoystick.Horizontal + Vector3.up * variableJoystick.Vertical);
        }

        /// <summary>
        /// 맵 범위를 고려한 목표 위치 계산
        /// </summary>
        private Vector3 CalculateTargetPosition(Vector3 moveDirection)
        {
            float deltaSpeed = playerCharactor.MoveSpeed * Time.deltaTime;
            Vector3 rawTargetPosition = player.transform.position + moveDirection * deltaSpeed;

            // 맵 경계 확인
            Bounds mapBounds = mapRange.bounds;

            // 맵 범위 내로 제한
            Vector3 clampedPosition = new Vector3(
                Mathf.Clamp(rawTargetPosition.x, mapBounds.min.x, mapBounds.max.x),
                Mathf.Clamp(rawTargetPosition.y, mapBounds.min.y, mapBounds.max.y),
                rawTargetPosition.z
            );

            return clampedPosition;
        }

        /// <summary>
        /// 플레이어를 목표 위치로 이동
        /// </summary>
        private void MovePlayer(Vector3 targetPosition)
        {
            player.transform.DOMove(targetPosition, moveDuration);
        }

        /// <summary>
        /// 플레이어 애니메이션 상태 업데이트
        /// </summary>
        private void UpdateAnimationState(float moveMagnitude)
        {
            if (_playerAnimator != null)
            {
                _playerAnimator.SetFloat("Walk", moveMagnitude);
            }
        }

        /// <summary>
        /// 이동 중 공격 시도
        /// </summary>
        private void TryAttack(Vector3 moveDirection)
        {
            if (moveDirection.magnitude > 0.1f && !_isAttack)
            {
                PlayerAttack(moveDirection).Forget();
            }
        }

        /// <summary>
        /// 이동 방향에 따른 캐릭터 회전 처리
        /// </summary>
        private void UpdateCharacterRotation(Vector3 moveDirection)
        {
            if (moveDirection != Vector3.zero && playerCharactor != null)
            {
                float angle = Mathf.Atan2(moveDirection.y, moveDirection.x) * Mathf.Rad2Deg;
                float yRotation = (angle > 90 || angle < -90) ? 0f : 180f;
                playerCharactor.transform.rotation = Quaternion.Euler(0, yRotation, 0);
            }
        }

        /// <summary>
        /// 플레이어 공격 호출 
        /// </summary>
        /// <param name="attackAngle">공격 방향</param>
        private async UniTask PlayerAttack(Vector3 attackAngle)
        {
            _isAttack = true;
            playerCharactor.AttackAngle = attackAngle;
            playerCharactor.PlayState = PlayerBase.PlayerState.Attack;

            await UniTask.Delay(100);
            _isAttack = false;
        }

        #endregion

        #region 카메라 제어

        /// <summary>
        /// 카메라 추적 
        /// </summary>
        private void FallowCamera()
        {
            // playerCharactor, cameraTransform, mapRange가 모두 할당되었는지 확인
            if (playerCharactor == null || cameraTransform == null || mapRange == null)
            {
                // 필수 컴포넌트가 없으면 카메라 추적을 시도하지 않음
                return;
            }

            // 카메라가 맵 경계를 벗어나지 않도록 설정
            Vector3 cameraPosition = new Vector3(playerCharactor.transform.position.x,
                playerCharactor.transform.position.y, cameraTransform.transform.position.z);

            // 맵 범위의 경계를 가져옴
            Bounds mapBounds = mapRange.bounds;

            // 카메라의 절반 크기를 계산
            float cameraHalfWidth = cameraTransform.orthographicSize * cameraTransform.aspect;
            float cameraHalfHeight = cameraTransform.orthographicSize;

            // 맵 범위 내에서 카메라 위치를 클램프
            cameraPosition.x = Mathf.Clamp(cameraPosition.x, mapBounds.min.x + cameraHalfWidth,
                mapBounds.max.x - cameraHalfWidth);
            cameraPosition.y = Mathf.Clamp(cameraPosition.y, mapBounds.min.y + cameraHalfHeight,
                mapBounds.max.y - cameraHalfHeight);

            cameraTransform.transform.DOMove(cameraPosition, moveDuration);
        }

        #endregion

        #region 자동 이동 및 공격 설정



        public bool AutoAttackEnabledByToggle
        {
            get => _autoAttackEnabledByToggle;
            set
            {
                _autoAttackEnabledByToggle = value;
                if (value)
                {
                    EnableAutoMoveAttack();
                }
                else
                {
                    DisableAutoMoveAttack();
                }
            }
        }

        // 플레이어 자동 이동 및 공격 루프
        private CancellationTokenSource _autoMoveAttackCTS;
        public void EnableAutoMoveAttack()
        {
            if (_autoMoveAttackCTS != null)
            {
                _autoMoveAttackCTS.Cancel();
                _autoMoveAttackCTS.Dispose();
            }
            _autoMoveAttackCTS = new CancellationTokenSource();
            AutoMoveAttackLoop(_autoMoveAttackCTS.Token).Forget();
        }

        public void DisableAutoMoveAttack()
        {
            if (_autoMoveAttackCTS != null)
            {
                _autoMoveAttackCTS.Cancel();
                _autoMoveAttackCTS.Dispose();
                _autoMoveAttackCTS = null;
            }
        }

        private async UniTaskVoid AutoMoveAttackLoop(CancellationToken token)
        {
            while (!token.IsCancellationRequested)
            {
                if (!_isGameStart || playerCharactor == null)
                {
                    await UniTask.Yield();
                    continue;
                }

                // 가장 가까운 적 찾기
                GameObject closestEnemy = FindClosestEnemy();
                if (closestEnemy != null)
                {
                    Vector3 enemyPos = closestEnemy.transform.position;
                    Vector3 playerPos = player.transform.position;
                    Vector3 dir = (enemyPos - playerPos).normalized;
                    float distance = Vector3.Distance(playerPos, enemyPos);
                    float stopDistance = autoAttackStopDistance; // 인스펙터에서 설정

                    // 사거리 밖이면 적 방향으로 이동
                    if (distance > stopDistance)
                    {
                        Vector3 targetPosition = player.transform.position + dir * (playerCharactor.MoveSpeed * autoAttackMoveSpeedMultiplier * Time.deltaTime);
                        // 맵 경계 확인 및 클램프
                        Bounds mapBounds = mapRange.bounds;
                        targetPosition = new Vector3(
                            Mathf.Clamp(targetPosition.x, mapBounds.min.x, mapBounds.max.x),
                            Mathf.Clamp(targetPosition.y, mapBounds.min.y, mapBounds.max.y),
                            targetPosition.z
                        );
                        MovePlayer(targetPosition);
                        UpdateAnimationState(dir.magnitude);
                        UpdateCharacterRotation(dir);
                    }
                    else
                    {
                        // 사거리 안이면 공격
                        if (!_isAttack)
                        {
                            await PlayerAttack(dir);
                        }
                        UpdateAnimationState(0f);
                    }
                }
                else
                {
                    // 적이 없으면 Idle
                    UpdateAnimationState(0f);
                }

                await UniTask.Yield(PlayerLoopTiming.Update);
            }
        }

        private GameObject FindClosestEnemy()
        {
            GameObject[] enemies = GameObject.FindGameObjectsWithTag("Mob");
            GameObject closest = null;
            float minDist = float.MaxValue;
            Vector3 playerPos = player.transform.position;
            foreach (var enemy in enemies)
            {
                float dist = Vector3.Distance(playerPos, enemy.transform.position);
                if (dist < minDist)
                {
                    minDist = dist;
                    closest = enemy;
                }
            }
            return closest;
        }

        #endregion
    }
}

using System.Threading;
using Cysharp.Threading.Tasks;
using UnityEngine;
using DG.Tweening;
using UnityEngine.UI;

namespace DogGuns_Games.vamsir
{
    public class VamPlayerControll : MonoBehaviour
    {

        //todo 아직 맵안에 들어오지 않은 적은 자동공격에 탐색되지않게 

        #region 필드 및 변수

        [Header("<color=green>Player Object")] [SerializeField]
        private GameObject player;

        [Header("<color=green>Player charactor Object")] [SerializeField]
        private PlayerBase playerCharactor;

        [Header("<color=green>Player HP_IU")] [SerializeField]
        private Slider playerHpSliderPrefab;

        private float _playerHpSliderValue = 0;

        private Animator _playerAnimator;

        [Header("<color=green>Joystick")] [SerializeField]
        private VariableJoystick variableJoystick;

        [Header("<color=green>camera")] [SerializeField]
        private Camera cameraTransform;

        [Header("<color=green>Move Duration")] [SerializeField]
        private float moveDuration = 0.1f;


        private Slider _playerHpSlider; // 인스턴스화된 슬라이더 참조 추가

        [Header("<color=green>Map Range")] [SerializeField]
        private SpriteRenderer mapRange;


        bool _isGameStart = false;

        bool _isAttack = false;

        [Header("<color=green>자동 공격 설정")] 
        [Tooltip("자동 공격 시 플레이어가 멈추는 거리(공격 사거리)")]
        public float autoAttackStopDistance = 1.5f;
        [Tooltip("자동 공격 시 이동 속도 배율")]
        public float autoAttackMoveSpeedMultiplier = 1.0f;

        private bool _isJoystickActive = false;
        private bool _autoAttackEnabledByToggle = true;

        private float joystickInputThreshold = 0.1f;
        private float joystickIdleTime = 0.2f; // 입력이 없을 때 자동공격 재활성화까지 대기 시간
        private float joystickIdleTimer = 0f;
        private bool _autoAttackActive = false;

        private bool _isAutoMoveAttackEnabled = false;


        #endregion

        #region Unity 라이프사이클

        private void Start()
        {
            PlayStateManager.OnGameStart += PlayerInit;
            PlayStateManager.OnGamePause += Pause;
            PlayStateManager.OnGameResume += Resume;
            PlayStateManager.OnGameOver += OnGameOver;
        }

        private void OnDestroy()
        {
            PlayStateManager.OnGameStart -= PlayerInit;
            PlayStateManager.OnGamePause -= Pause;
            PlayStateManager.OnGameResume -= Resume;
            PlayStateManager.OnGameOver -= OnGameOver;
        }

        private void OnGameOver()
        {
            DisableAutoMoveAttack();
            _autoAttackActive = false;
        }

        private void OnJoystickDown()
        {
            _isJoystickActive = true;
            if (_autoAttackEnabledByToggle)
                DisableAutoMoveAttack();
        }

        private void OnJoystickUp()
        {
            _isJoystickActive = false;
            if (_autoAttackEnabledByToggle)
                EnableAutoMoveAttack();
        }

        public void SetAutoAttackToggle(bool isOn)
        {
            _autoAttackEnabledByToggle = isOn;
            if (!isOn && _autoAttackActive)
            {
                DisableAutoMoveAttack();
                _autoAttackActive = false;
            }
            joystickIdleTimer = 0f;
        }

        private void FixedUpdate()
        {
            if (_isGameStart)
            {
                PlayerMovement();
                FallowCamera();
                UpdatePlayerHpSlider();

                // VariableJoystick 수정 없이 입력값 감지
                float inputMagnitude = Mathf.Abs(variableJoystick.Horizontal) + Mathf.Abs(variableJoystick.Vertical);
                if (_autoAttackEnabledByToggle)
                {
                    if (inputMagnitude > joystickInputThreshold)
                    {
                        // 조이스틱 조작 중: 자동공격 비활성화
                        joystickIdleTimer = 0f;
                        if (_autoAttackActive)
                        {
                            DisableAutoMoveAttack();
                            _autoAttackActive = false;
                        }
                    }
                    else
                    {

                        // 조이스틱 입력 없음: 일정 시간 후 자동공격 재활성화
                        joystickIdleTimer += Time.fixedDeltaTime;
                        if (_autoAttackActive && joystickIdleTimer > joystickIdleTime)
                        {
                            EnableAutoMoveAttack();
                        }
                    }
                }
                else
                {
                    if (_autoAttackActive)
                    {
                        DisableAutoMoveAttack();
                        _autoAttackActive = false;
                    }
                }
            }
        }

        #endregion

        #region 게임 상태 관리

        private void PlayerInit()
        {
            // 캐릭터 스폰과의 레이스 컨디션을 피하기 위해 초기화 로직을 AssignCharacter로 이동했습니다.
            // OnGameStart 이벤트에서는 게임 시작 플래그만 설정합니다.
            _isGameStart = true;
        }

        /// <summary>
        /// VamserLikeGameManager가 플레이어 스폰 후 호출하여 캐릭터를 설정합니다.
        /// </summary>
        /// <param name="character">스폰된 플레이어 캐릭터</param>
        public void AssignCharacter(PlayerBase character)
        {
            if (playerCharactor == null && character != null)
            {
                playerCharactor = character;
                playerCharactor.transform.SetParent(player.gameObject.transform);
                _playerAnimator = playerCharactor.GetComponent<Animator>();
                cameraTransform = Camera.main;
                Set_playerHpSlider();
            }
        }

        private void Pause()
        {
            _isGameStart = false;
        }

        private void Resume()
        {
            _isGameStart = true;
        }

        #endregion

        #region UI 설정

        private void Set_playerHpSlider()
        {
            _playerHpSlider = Instantiate(playerHpSliderPrefab, player.transform);
            _playerHpSlider.transform.localPosition = new Vector3(0, -0.4f, 0);
            _playerHpSlider.maxValue = playerCharactor.Health;
            _playerHpSlider.value = playerCharactor.Health;
            _playerHpSliderValue = playerCharactor.Health;
        }

        private void UpdatePlayerHpSlider()
        {
            if (playerCharactor == null)
            {
                PlayerInit();
                return;
            }

            // 현재 체력 값이 이전 값과 다를 때만 슬라이더 업데이트
            if (_playerHpSlider != null && Mathf.Abs(_playerHpSliderValue - playerCharactor.Health) > 0.001f)
            {
                _playerHpSliderValue = playerCharactor.Health;
                _playerHpSlider.value = _playerHpSliderValue;

                // 게임 오버 처리는 PlayerBase의 Player_Hit에서 담당하므로 여기서는 제거
                // PlayerBase에서 Health <= 0일 때 자동으로 게임 오버 처리됨
            }
        }

        #endregion

        #region 플레이어 제어

        /// <summary>
        /// 플레이어 이동을 처리하는 메서드
        /// </summary>
        private void PlayerMovement()
        {
            // 플레이어 객체 유효성 검사
            if (player == null || playerCharactor == null)
            {
                // PlayerInit(); // 재귀 호출 및 로직 문제로 제거
                return;
            }

            // 이동 입력 및 위치 계산
            Vector3 moveDirection = GetJoystickInputDirection();
            Vector3 targetPosition = CalculateTargetPosition(moveDirection);

            // 실제 이동 처리
            MovePlayer(targetPosition);

            // 애니메이션 및 회전 처리
            UpdateAnimationState(moveDirection.magnitude);

            // 공격 처리
            TryAttack(moveDirection);

            // 캐릭터 회전 처리
            UpdateCharacterRotation(moveDirection);
        }

        /// <summary>
        /// 조이스틱 입력을 방향 벡터로 변환
        /// </summary>
        private Vector3 GetJoystickInputDirection()
        {
            return (Vector3.right * variableJoystick.Horizontal + Vector3.up * variableJoystick.Vertical);
        }

        /// <summary>
        /// 맵 범위를 고려한 목표 위치 계산
        /// </summary>
        private Vector3 CalculateTargetPosition(Vector3 moveDirection)
        {
            float deltaSpeed = playerCharactor.MoveSpeed * Time.deltaTime;
            Vector3 rawTargetPosition = player.transform.position + moveDirection * deltaSpeed;

            // 맵 경계 확인
            Bounds mapBounds = mapRange.bounds;

            // 맵 범위 내로 제한
            Vector3 clampedPosition = new Vector3(
                Mathf.Clamp(rawTargetPosition.x, mapBounds.min.x, mapBounds.max.x),
                Mathf.Clamp(rawTargetPosition.y, mapBounds.min.y, mapBounds.max.y),
                rawTargetPosition.z
            );

            return clampedPosition;
        }

        /// <summary>
        /// 플레이어를 목표 위치로 이동
        /// </summary>
        private void MovePlayer(Vector3 targetPosition)
        {
            player.transform.DOMove(targetPosition, moveDuration);
        }

        /// <summary>
        /// 플레이어 애니메이션 상태 업데이트
        /// </summary>
        private void UpdateAnimationState(float moveMagnitude)
        {
            if (_playerAnimator != null)
            {
                _playerAnimator.SetFloat("Walk", moveMagnitude);
            }
        }

        /// <summary>
        /// 이동 중 공격 시도
        /// </summary>
        private void TryAttack(Vector3 moveDirection)
        {
            if (moveDirection.magnitude > 0.1f && !_isAttack)
            {
                PlayerAttack(moveDirection).Forget();
            }
        }

        /// <summary>
        /// 이동 방향에 따른 캐릭터 회전 처리
        /// </summary>
        private void UpdateCharacterRotation(Vector3 moveDirection)
        {
            if (moveDirection != Vector3.zero && playerCharactor != null)
            {
                float angle = Mathf.Atan2(moveDirection.y, moveDirection.x) * Mathf.Rad2Deg;
                float yRotation = (angle > 90 || angle < -90) ? 0f : 180f;
                playerCharactor.transform.rotation = Quaternion.Euler(0, yRotation, 0);
            }
        }

        /// <summary>
        /// 플레이어 공격 호출 
        /// </summary>
        /// <param name="attackAngle">공격 방향</param>
        private async UniTask PlayerAttack(Vector3 attackAngle)
        {
            _isAttack = true;
            playerCharactor.AttackAngle = attackAngle;
            playerCharactor.PlayState = PlayerBase.PlayerState.Attack;

            await UniTask.Delay(100);
            _isAttack = false;
        }

        #endregion

        #region 카메라 제어

        /// <summary>
        /// 카메라 추적 
        /// </summary>
        private void FallowCamera()
        {
            // playerCharactor, cameraTransform, mapRange가 모두 할당되었는지 확인
            if (playerCharactor == null || cameraTransform == null || mapRange == null)
            {
                // 필수 컴포넌트가 없으면 카메라 추적을 시도하지 않음
                return;
            }

            // 카메라가 맵 경계를 벗어나지 않도록 설정
            Vector3 cameraPosition = new Vector3(playerCharactor.transform.position.x,
                playerCharactor.transform.position.y, cameraTransform.transform.position.z);

            // 맵 범위의 경계를 가져옴
            Bounds mapBounds = mapRange.bounds;

            // 카메라의 절반 크기를 계산
            float cameraHalfWidth = cameraTransform.orthographicSize * cameraTransform.aspect;
            float cameraHalfHeight = cameraTransform.orthographicSize;

            // 맵 범위 내에서 카메라 위치를 클램프
            cameraPosition.x = Mathf.Clamp(cameraPosition.x, mapBounds.min.x + cameraHalfWidth,
                mapBounds.max.x - cameraHalfWidth);
            cameraPosition.y = Mathf.Clamp(cameraPosition.y, mapBounds.min.y + cameraHalfHeight,
                mapBounds.max.y - cameraHalfHeight);

            cameraTransform.transform.DOMove(cameraPosition, moveDuration);
        }

        #endregion

        #region 자동 이동 및 공격 설정



        public bool AutoAttackEnabledByToggle
        {
            get => _autoAttackEnabledByToggle;
            set
            {
                _autoAttackEnabledByToggle = value;
                if (value)
                {
                    EnableAutoMoveAttack();
                }
                else
                {
                    DisableAutoMoveAttack();
                }
            }
        }

        // 플레이어 자동 이동 및 공격 루프
        private CancellationTokenSource _autoMoveAttackCTS;
        public void EnableAutoMoveAttack()
        {
            if (_autoMoveAttackCTS != null)
            {
                _autoMoveAttackCTS.Cancel();
                _autoMoveAttackCTS.Dispose();
            }
            _autoMoveAttackCTS = new CancellationTokenSource();
            AutoMoveAttackLoop(_autoMoveAttackCTS.Token).Forget();
        }

        public void DisableAutoMoveAttack()
        {
            if (_autoMoveAttackCTS != null)
            {
                _autoMoveAttackCTS.Cancel();
                _autoMoveAttackCTS.Dispose();
                _autoMoveAttackCTS = null;
            }
        }

        private async UniTaskVoid AutoMoveAttackLoop(CancellationToken token)
        {
            while (!token.IsCancellationRequested)
            {
                if (!_isGameStart || playerCharactor == null)
                {
                    await UniTask.Yield();
                    continue;
                }

                // 가장 가까운 적 찾기
                GameObject closestEnemy = FindClosestEnemy();
                if (closestEnemy != null)
                {
                    Vector3 enemyPos = closestEnemy.transform.position;
                    Vector3 playerPos = player.transform.position;
                    Vector3 dir = (enemyPos - playerPos).normalized;
                    float distance = Vector3.Distance(playerPos, enemyPos);
                    float stopDistance = autoAttackStopDistance; // 인스펙터에서 설정

                    // 사거리 밖이면 적 방향으로 이동
                    if (distance > stopDistance)
                    {
                        Vector3 targetPosition = player.transform.position + dir * (playerCharactor.MoveSpeed * autoAttackMoveSpeedMultiplier * Time.deltaTime);
                        // 맵 경계 확인 및 클램프
                        Bounds mapBounds = mapRange.bounds;
                        targetPosition = new Vector3(
                            Mathf.Clamp(targetPosition.x, mapBounds.min.x, mapBounds.max.x),
                            Mathf.Clamp(targetPosition.y, mapBounds.min.y, mapBounds.max.y),
                            targetPosition.z
                        );
                        MovePlayer(targetPosition);
                        UpdateAnimationState(dir.magnitude);
                        UpdateCharacterRotation(dir);
                    }
                    else
                    {
                        // 사거리 안이면 공격
                        if (!_isAttack)
                        {
                            await PlayerAttack(dir);
                        }
                        UpdateAnimationState(0f);
                    }
                }
                else
                {
                    // 적이 없으면 Idle
                    UpdateAnimationState(0f);
                }

                await UniTask.Yield(PlayerLoopTiming.Update);
            }
        }

        private GameObject FindClosestEnemy()
        {
            GameObject[] enemies = GameObject.FindGameObjectsWithTag("Mob");
            GameObject closest = null;
            float minDist = float.MaxValue;
            Vector3 playerPos = player.transform.position;
            Bounds mapBounds = mapRange != null ? mapRange.bounds : new Bounds(Vector3.zero, Vector3.one * 9999f);
            foreach (var enemy in enemies)
            {
                Vector3 enemyPos = enemy.transform.position;
                // 맵 안에 있는 적만 탐색
                if (enemyPos.x < mapBounds.min.x || enemyPos.x > mapBounds.max.x ||
                    enemyPos.y < mapBounds.min.y || enemyPos.y > mapBounds.max.y)
                {
                    continue;
                }
                float dist = Vector3.Distance(playerPos, enemyPos);
                if (dist < minDist)
                {
                    minDist = dist;
                    closest = enemy;
                }
            }
            return closest;
        }

        #endregion
    }
}

using System.Collections.Generic;
using System.Threading;
using Cysharp.Threading.Tasks;
using TMPro;
using UnityEngine;
using UnityEngine.UI;
using DG.Tweening;


namespace DogGuns_Games.vamsir
{
    public class VamserLikeUI : MonoBehaviour
    {
        #region 필드 및 변수

        [Header("<color=green>User Info UI")] [SerializeField]
        private TMP_Text LevelText;

        [SerializeField] private Slider playerLevelSlider;

        [Header("<color=green>Text UI")] [SerializeField]
        private TMP_Text mobWaveText;

        [SerializeField] private TMP_Text coinText;
        [SerializeField] private TMP_Text mobCountText;
        [SerializeField] private TMP_Text playerLevelText;
        [SerializeField] private Slider expSlider;
        private int getcoinCount = 0; // 초기화 전 코인 정보를 담을 변수

        [Header("<color=green>Menu UI")] [SerializeField]
        private Button menuBtn;

        [SerializeField] private GameObject menuPanel;
        [SerializeField] private Button settingBtn;
        [SerializeField] private Button exitBtn;
        public List<GameObject> weaponUIList = new List<GameObject>();
        public List<GameObject> juListUIList = new List<GameObject>();

        [Header("<color=green>GameOver UI")] [SerializeField]
        private GameObject gameOverPanel;

        [SerializeField] private Button gameOverExitBtn;
        [SerializeField] private Button gameOverRestartBtn;
        [SerializeField] private TMP_Text gameOverText;
        [SerializeField] private TMP_Text gameOverCoinText;
        [SerializeField] private TMP_Text gameOverWaveText;
        [SerializeField] private TMP_Text gameOverMobCountText;


        [Header("<color=green>조이스틱")] [SerializeField]
        private VariableJoystick variableJoystick;

        [Header("<color=green>플레이어 자동 공격 활성화 토글 ")] [SerializeField]
        private Toggle autoAttackToggle;

        [SerializeField] private Transform joystickTransform;
        VamserLikeGameManager _gameManager;
        private CancellationTokenSource _cancellationTokenSource;

        #endregion

        #region Unity 라이프사이클

        private void Awake()
        {
            _gameManager = FindFirstObjectByType<VamserLikeGameManager>();
        }

        private void Start()
        {
            PlayStateManager.OnGameStart += GameStart;
            PlayStateManager.OnGamePause += Pause;
            PlayStateManager.OnGameResume += Resume;
            PlayStateManager.OnGameOver += ShowGameOverPopup;
            // 플레이어 경험치 이벤트 구독
            PlayerBase.OnExpChanged += OnPlayerExpChanged;
            PlayerBase.OnLevelUp += OnPlayerLevelUp;

            _gameManager = FindFirstObjectByType<VamserLikeGameManager>();
            // 자동 공격 토글 이벤트 연결
            autoAttackToggle.onValueChanged.AddListener(isOn =>
            {
                AutoAttackEnabledByToggle
            });
        }

        private void OnDestroy()
        {
            _cancellationTokenSource?.Cancel();

            // 이벤트 구독 해제 추가
            PlayStateManager.OnGameStart -= GameStart;
            PlayStateManager.OnGamePause -= Pause;
            PlayStateManager.OnGameResume -= Resume;
            PlayStateManager.OnGameOver -= ShowGameOverPopup;

            // 플레이어 경험치 이벤트 구독 해제
            PlayerBase.OnExpChanged -= OnPlayerExpChanged;
            PlayerBase.OnLevelUp -= OnPlayerLevelUp;
        }

        #endregion

        #region 게임 상태 관리

        private void GameStart()
        {
            BtnSetting();
            JoystickSetting();
            SoundSetting(); // 사운드 설정 추가
            _cancellationTokenSource = new CancellationTokenSource();
            UpdateUI(_cancellationTokenSource.Token).Forget();
        }

        private void Pause()
        {
            joystickTransform.gameObject.SetActive(false);
        }

        private void Resume()
        {
            joystickTransform.gameObject.SetActive(true);
            JoystickSetting();
        }

        #endregion

        #region UI 설정 및 초기화

        private void JoystickSetting()
        {
            if (variableJoystick == null)
            {
                variableJoystick = FindFirstObjectByType<VariableJoystick>();
            }

            if (SoundManager.Instance == null)
            {
                LogManager.LogError("SoundManager.Instance가 null입니다. 씬에 SoundManager가 배치되어 있는지 확인하세요.",
                    LogManager.LogCategory.VamserLikeUI);
                return;
            }

            var settingsData = SoundManager.Instance.settingsData;
            if (settingsData == null)
            {
                LogManager.LogError("SoundManager의 settingsData가 null입니다. 인스펙터에서 할당되어 있는지 확인하세요.",
                    LogManager.LogCategory.VamserLikeUI);
                return;
            }

            joystickTransform.localScale = new Vector3(settingsData.joystickSize,
                settingsData.joystickSize, 1);
            variableJoystick.SetMode((JoystickType)settingsData.joystickType);
            var rectTransform = joystickTransform as RectTransform;
            if (rectTransform != null)
                rectTransform.anchoredPosition = settingsData.joystickPos;
        }


        private void SoundSetting()
        {
            SoundManager.Instance.LoadSoundSetting();
        }


        private void BtnSetting()
        {
            menuBtn.onClick.AddListener(PausePopUp);

            exitBtn.onClick.AddListener(PausePopUp);

            settingBtn.onClick.AddListener(() => { _gameManager.Open_OptionPopUp(); });

            // 게임 오버 버튼 설정
            gameOverExitBtn.onClick.AddListener(GameOverExit);
            gameOverRestartBtn.onClick.AddListener(GameOverRestart);
        }

        #endregion

        #region UI 이벤트 및 동작

        private void PausePopUp()
        {
            // 메뉴 패널의 현재 활성 상태의 반대로 설정합니다.
            bool isMenuPanelBecomingActive = !menuPanel.activeSelf;
            menuPanel.SetActive(isMenuPanelBecomingActive);

            // isMenuPanelBecomingActive 값에 따라 게임의 Pause/Resume 상태를 설정합니다.
            _gameManager.Open_MenuPopUp(isMenuPanelBecomingActive);

            // 메뉴 패널이 활성화되면 조이스틱을 비활성화하고, 그 반대의 경우도 마찬가지입니다.
            joystickTransform.gameObject.SetActive(!isMenuPanelBecomingActive);
        }

        private void GameOverExit()
        {
            // 게임 오버 패널을 비활성화하고, 로비 씬으로 이동
            gameOverPanel.SetActive(false);
            SceneLoader.Instance.LoadLobbyScene();
        }

        private void GameOverRestart()
        {
            // 게임 오버 패널을 비활성화하고, 게임을 다시 시작
            gameOverPanel.SetActive(false);
            // 씬을 다시 로드하여 게임을 재시작
            UnityEngine.SceneManagement.SceneManager.LoadScene(
                UnityEngine.SceneManagement.SceneManager.GetActiveScene().name);
        }

        #endregion

        #region 게임 오버

        /// <summary>
        /// 게임 오버 팝업을 표시합니다.
        /// </summary>
        public void ShowGameOverPopup()
        {
            // 게임 오버 UI 데이터 업데이트
            UpdateGameOverUI();

            // 게임 오버 패널 활성화
            gameOverPanel.SetActive(true);

            // 조이스틱 비활성화 및 위치/상태 초기화
            joystickTransform.gameObject.SetActive(false);
            if (variableJoystick != null)
            {
                variableJoystick.OnPointerUp(null); // 입력 해제
            }

            autoAttackToggle.isOn = false; // 자동 공격 토글 비활성화

            // 취소 토큰 소스가 있다면 취소합니다.
            _cancellationTokenSource?.Cancel();
        }

        /// <summary>
        /// 게임 오버 UI의 텍스트들을 업데이트합니다.
        /// </summary>
        private void UpdateGameOverUI()
        {
            gameOverText.text = "Game Over";
            gameOverCoinText.text = $"Coins: {getcoinCount}";
            gameOverWaveText.text = $"Wave: {_gameManager.MobSpawnWave()}";
            gameOverMobCountText.text = $"Kills: {_gameManager.Mob_Count()}";
        }

        #endregion

        #region UI 업데이트

        private async UniTask UpdateUI(CancellationToken cancellationToken)
        {
            string lastWaveText = "";
            while (!cancellationToken.IsCancellationRequested)
            {
                string currentWaveText = $"Wave {_gameManager.MobSpawnWave()}";
                if (mobWaveText.text != currentWaveText)
                {
                    await WaveTextFadeEffect(currentWaveText);
                    lastWaveText = currentWaveText;
                }

                coinText.text = $"{_gameManager.CoinCount()}";
                getcoinCount = _gameManager.CoinCount();
                mobCountText.text = $"{_gameManager.Mob_Count()}";
                playerLevelText.text = $"Lv. {_gameManager.PlayerLevel()}";
                // User Info UI 업데이트
                UpdatePlayerLevelUI();
                await UniTask.DelayFrame(1, PlayerLoopTiming.FixedUpdate, cancellationToken);
            }
        }

        // DOTween을 이용한 mobWaveText 페이드 인/아웃 효과
        private async UniTask WaveTextFadeEffect(string waveText)
        {
            mobWaveText.text = waveText;
            mobWaveText.alpha = 0f;
            mobWaveText.gameObject.SetActive(true);
            await mobWaveText.DOFade(1f, 0.5f).AsyncWaitForCompletion(); // 페이드 인
            await UniTask.Delay(1000); // 1초간 표시
            await mobWaveText.DOFade(0f, 0.5f).AsyncWaitForCompletion(); // 페이드 아웃
            mobWaveText.gameObject.SetActive(false);
        }

        /// <summary>
        /// 플레이어 레벨 UI를 업데이트합니다.
        /// </summary>
        private void UpdatePlayerLevelUI()
        {
            float currentLevel = _gameManager.PlayerLevel();
            LevelText.text = $"Lv. {currentLevel:F0}";

            // 실제 경험치 시스템 사용
            float expProgress = _gameManager.GetPlayerExpProgress();
            playerLevelSlider.value = expProgress;

            // 기존 expSlider도 같은 값으로 업데이트 (중복 슬라이더가 있는 경우)
            if (expSlider != null)
            {
                expSlider.value = expProgress;
            }
        }

        #endregion

        #region 플레이어 경험치 및 레벨 이벤트

        /// <summary>
        /// 플레이어 경험치가 변경되었을 때 호출되는 메서��입니다.
        /// </summary>
        private void OnPlayerExpChanged(float currentExp, float maxExp)
        {
            // 실시간으로 경험치 UI 업데이트
            UpdatePlayerLevelUI();
            // 디버그 로그 (선택사항)
            LogManager.Log($"경험치 UI 업데이트: {currentExp:F1}/{maxExp:F1} ({(currentExp / maxExp) * 100:F1}%)",
                LogManager.LogCategory.VamserLikeUI);
        }

        /// <summary>
        /// 플레이어 레벨업 시 호출되는 메서드입니다.
        /// </summary>
        private void OnPlayerLevelUp(float newLevel)
        {
            // 레벨업 시 UI 업데이트
            UpdatePlayerLevelUI();
            // 레벨업 축하 효과 (선택사항)
            ShowLevelUpEffect(newLevel);
            LogManager.Log($"레벨업 UI 업데이트: 새 레벨 {newLevel}", LogManager.LogCategory.VamserLikeUI);
        }

        /// <summary>
        /// 레벨업 시 시각적 효과를 표시합니다.
        /// </summary>
        private void ShowLevelUpEffect(float newLevel)
        {
            // 레벨 텍스트에 간단한 효과 적용 (선택사항)
            if (LevelText != null)
            {
                // 크기 변화 효과 (DOTween 사용)
                LevelText.transform.localScale = Vector3.one * 1.2f;
                LevelText.transform.DOScale(Vector3.one, 0.3f)
                    .SetEase(Ease.OutBack);

                // 색상 변화 효과 (DOTween 사용)
                Color originalColor = LevelText.color;
                LevelText.color = Color.yellow;
                LevelText.DOColor(originalColor, 1f);
            }
        }

        #endregion
    }
}

using System.Collections.Generic;
using System.Threading;
using Cysharp.Threading.Tasks;
using TMPro;
using UnityEngine;
using UnityEngine.UI;
using DG.Tweening;


namespace DogGuns_Games.vamsir
{
    public class VamserLikeUI : MonoBehaviour
    {
        #region 필드 및 변수

        [Header("<color=green>User Info UI")] [SerializeField]
        private TMP_Text LevelText;

        [SerializeField] private Slider playerLevelSlider;

        [Header("<color=green>Text UI")] [SerializeField]
        private TMP_Text mobWaveText;

        [SerializeField] private TMP_Text coinText;
        [SerializeField] private TMP_Text mobCountText;
        [SerializeField] private TMP_Text playerLevelText;
        [SerializeField] private Slider expSlider;
        private int getcoinCount = 0; // 초기화 전 코인 정보를 담을 변수

        [Header("<color=green>Menu UI")] [SerializeField]
        private Button menuBtn;

        [SerializeField] private GameObject menuPanel;
        [SerializeField] private Button settingBtn;
        [SerializeField] private Button exitBtn;
        public List<GameObject> weaponUIList = new List<GameObject>();
        public List<GameObject> juListUIList = new List<GameObject>();

        [Header("<color=green>GameOver UI")] [SerializeField]
        private GameObject gameOverPanel;

        [SerializeField] private Button gameOverExitBtn;
        [SerializeField] private Button gameOverRestartBtn;
        [SerializeField] private TMP_Text gameOverText;
        [SerializeField] private TMP_Text gameOverCoinText;
        [SerializeField] private TMP_Text gameOverWaveText;
        [SerializeField] private TMP_Text gameOverMobCountText;


        [Header("<color=green>조이스틱")] [SerializeField]
        private VariableJoystick variableJoystick;

        [Header("<color=green>플레이어 자동 공격 활성화 토글 ")] [SerializeField]
        private Toggle autoAttackToggle;

        [SerializeField] private Transform joystickTransform;
        VamserLikeGameManager _gameManager;
        private CancellationTokenSource _cancellationTokenSource;

        #endregion

        #region Unity 라이프사이클

        private void Awake()
        {
            _gameManager = FindFirstObjectByType<VamserLikeGameManager>();
        }

        private void Start()
        {
            PlayStateManager.OnGameStart += GameStart;
            PlayStateManager.OnGamePause += Pause;
            PlayStateManager.OnGameResume += Resume;
            PlayStateManager.OnGameOver += ShowGameOverPopup;
            // 플레이어 경험치 이벤트 구독
            PlayerBase.OnExpChanged += OnPlayerExpChanged;
            PlayerBase.OnLevelUp += OnPlayerLevelUp;

            _gameManager = FindFirstObjectByType<VamserLikeGameManager>();
            // 자동 공격 토글 이벤트 연결
            autoAttackToggle.onValueChanged.AddListener(isOn =>
            {
                // VamPlayerControll의 AutoAttackEnabledByToggle 프로퍼티에 값 전달
                var playerController = FindFirstObjectByType<VamPlayerControll>();
                if (playerController != null)
                {
                    playerController.AutoAttackEnabledByToggle = isOn;
                }
            });
        }

        private void OnDestroy()
        {
            _cancellationTokenSource?.Cancel();

            // 이벤트 구독 해제 추가
            PlayStateManager.OnGameStart -= GameStart;
            PlayStateManager.OnGamePause -= Pause;
            PlayStateManager.OnGameResume -= Resume;
            PlayStateManager.OnGameOver -= ShowGameOverPopup;

            // 플레이어 경험치 이벤트 구독 해제
            PlayerBase.OnExpChanged -= OnPlayerExpChanged;
            PlayerBase.OnLevelUp -= OnPlayerLevelUp;
        }

        #endregion

        #region 게임 상태 관리

        private void GameStart()
        {
            BtnSetting();
            JoystickSetting();
            SoundSetting(); // 사운드 설정 추가
            _cancellationTokenSource = new CancellationTokenSource();
            UpdateUI(_cancellationTokenSource.Token).Forget();
        }

        private void Pause()
        {
            joystickTransform.gameObject.SetActive(false);
        }

        private void Resume()
        {
            joystickTransform.gameObject.SetActive(true);
            JoystickSetting();
        }

        #endregion

        #region UI 설정 및 초기화

        private void JoystickSetting()
        {
            if (variableJoystick == null)
            {
                variableJoystick = FindFirstObjectByType<VariableJoystick>();
            }

            if (SoundManager.Instance == null)
            {
                LogManager.LogError("SoundManager.Instance가 null입니다. 씬에 SoundManager가 배치되어 있는지 확인하세요.",
                    LogManager.LogCategory.VamserLikeUI);
                return;
            }

            var settingsData = SoundManager.Instance.settingsData;
            if (settingsData == null)
            {
                LogManager.LogError("SoundManager의 settingsData가 null입니다. 인스펙터에서 할당되어 있는지 확인하세요.",
                    LogManager.LogCategory.VamserLikeUI);
                return;
            }

            joystickTransform.localScale = new Vector3(settingsData.joystickSize,
                settingsData.joystickSize, 1);
            variableJoystick.SetMode((JoystickType)settingsData.joystickType);
            var rectTransform = joystickTransform as RectTransform;
            if (rectTransform != null)
                rectTransform.anchoredPosition = settingsData.joystickPos;
        }


        private void SoundSetting()
        {
            SoundManager.Instance.LoadSoundSetting();
        }


        private void BtnSetting()
        {
            menuBtn.onClick.AddListener(PausePopUp);

            exitBtn.onClick.AddListener(PausePopUp);

            settingBtn.onClick.AddListener(() => { _gameManager.Open_OptionPopUp(); });

            // 게임 오버 버튼 설정
            gameOverExitBtn.onClick.AddListener(GameOverExit);
            gameOverRestartBtn.onClick.AddListener(GameOverRestart);
        }

        #endregion

        #region UI 이벤트 및 동작

        private void PausePopUp()
        {
            // 메뉴 패널의 현재 활성 상태의 반대로 설정합니다.
            bool isMenuPanelBecomingActive = !menuPanel.activeSelf;
            menuPanel.SetActive(isMenuPanelBecomingActive);

            // isMenuPanelBecomingActive 값에 따라 게임의 Pause/Resume 상태를 설정합니다.
            _gameManager.Open_MenuPopUp(isMenuPanelBecomingActive);

            // 메뉴 패널이 활성화되면 조이스틱을 비활성화하고, 그 반대의 경우도 마찬가지입니다.
            joystickTransform.gameObject.SetActive(!isMenuPanelBecomingActive);
        }

        private void GameOverExit()
        {
            // 게임 오버 패널을 비활성화하고, 로비 씬으로 이동
            gameOverPanel.SetActive(false);
            SceneLoader.Instance.LoadLobbyScene();
        }

        private void GameOverRestart()
        {
            // 게임 오버 패널을 비활성화하고, 게임을 다시 시작
            gameOverPanel.SetActive(false);
            // 씬을 다시 로드하여 게임을 재시작
            UnityEngine.SceneManagement.SceneManager.LoadScene(
                UnityEngine.SceneManagement.SceneManager.GetActiveScene().name);
        }

        #endregion

        #region 게임 오버

        /// <summary>
        /// 게임 오버 팝업을 표시합니다.
        /// </summary>
        public void ShowGameOverPopup()
        {
            // 게임 오버 UI 데이터 업데이트
            UpdateGameOverUI();

            // 게임 오버 패널 활성화
            gameOverPanel.SetActive(true);

            // 조이스틱 비활성화 및 위치/상태 초기화
            joystickTransform.gameObject.SetActive(false);
            if (variableJoystick != null)
            {
                variableJoystick.OnPointerUp(null); // 입력 해제
            }

            autoAttackToggle.isOn = false; // 자동 공격 토글 비활성화

            // 취소 토큰 소스가 있다면 취소합니다.
            _cancellationTokenSource?.Cancel();
        }

        /// <summary>
        /// 게임 오버 UI의 텍스트들을 업데이트합니다.
        /// </summary>
        private void UpdateGameOverUI()
        {
            gameOverText.text = "Game Over";
            gameOverCoinText.text = $"Coins: {getcoinCount}";
            gameOverWaveText.text = $"Wave: {_gameManager.MobSpawnWave()}";
            gameOverMobCountText.text = $"Kills: {_gameManager.Mob_Count()}";
        }

        #endregion

        #region UI 업데이트

        private async UniTask UpdateUI(CancellationToken cancellationToken)
        {
            string lastWaveText = "";
            while (!cancellationToken.IsCancellationRequested)
            {
                string currentWaveText = $"Wave {_gameManager.MobSpawnWave()}";
                if (mobWaveText.text != currentWaveText)
                {
                    await WaveTextFadeEffect(currentWaveText);
                    lastWaveText = currentWaveText;
                }

                coinText.text = $"{_gameManager.CoinCount()}";
                getcoinCount = _gameManager.CoinCount();
                mobCountText.text = $"{_gameManager.Mob_Count()}";
                playerLevelText.text = $"Lv. {_gameManager.PlayerLevel()}";
                // User Info UI 업데이트
                UpdatePlayerLevelUI();
                await UniTask.DelayFrame(1, PlayerLoopTiming.FixedUpdate, cancellationToken);
            }
        }

        // DOTween을 이용한 mobWaveText 페이드 인/아웃 효과
        private async UniTask WaveTextFadeEffect(string waveText)
        {
            mobWaveText.text = waveText;
            mobWaveText.alpha = 0f;
            mobWaveText.gameObject.SetActive(true);
            await mobWaveText.DOFade(1f, 0.5f).AsyncWaitForCompletion(); // 페이드 인
            await UniTask.Delay(1000); // 1초간 표시
            await mobWaveText.DOFade(0f, 0.5f).AsyncWaitForCompletion(); // 페이드 아웃
            mobWaveText.gameObject.SetActive(false);
        }

        /// <summary>
        /// 플레이어 레벨 UI를 업데이트합니다.
        /// </summary>
        private void UpdatePlayerLevelUI()
        {
            float currentLevel = _gameManager.PlayerLevel();
            LevelText.text = $"Lv. {currentLevel:F0}";

            // 실제 경험치 시스템 사용
            float expProgress = _gameManager.GetPlayerExpProgress();
            playerLevelSlider.value = expProgress;

            // 기존 expSlider도 같은 값으로 업데이트 (중복 슬라이더가 있는 경우)
            if (expSlider != null)
            {
                expSlider.value = expProgress;
            }
        }

        #endregion

        #region 플레이어 경험치 및 레벨 이벤트

        /// <summary>
        /// 플레이어 경험치가 변경되었을 때 호출되는 메서��입니다.
        /// </summary>
        private void OnPlayerExpChanged(float currentExp, float maxExp)
        {
            // 실시간으로 경험치 UI 업데이트
            UpdatePlayerLevelUI();
            // 디버그 로그 (선택사항)
            LogManager.Log($"경험치 UI 업데이트: {currentExp:F1}/{maxExp:F1} ({(currentExp / maxExp) * 100:F1}%)",
                LogManager.LogCategory.VamserLikeUI);
        }

        /// <summary>
        /// 플레이어 레벨업 시 호출되는 메서드입니다.
        /// </summary>
        private void OnPlayerLevelUp(float newLevel)
        {
            // 레벨업 시 UI 업데이트
            UpdatePlayerLevelUI();
            // 레벨업 축하 효과 (선택사항)
            ShowLevelUpEffect(newLevel);
            LogManager.Log($"레벨업 UI 업데이트: 새 레벨 {newLevel}", LogManager.LogCategory.VamserLikeUI);
        }

        /// <summary>
        /// 레벨업 시 시각적 효과를 표시합니다.
        /// </summary>
        private void ShowLevelUpEffect(float newLevel)
        {
            // 레벨 텍스트에 간단한 효과 적용 (선택사항)
            if (LevelText != null)
            {
                // 크기 변화 효과 (DOTween 사용)
                LevelText.transform.localScale = Vector3.one * 1.2f;
                LevelText.transform.DOScale(Vector3.one, 0.3f)
                    .SetEase(Ease.OutBack);

                // 색상 변화 효과 (DOTween 사용)
                Color originalColor = LevelText.color;
                LevelText.color = Color.yellow;
                LevelText.DOColor(originalColor, 1f);
            }
        }

        #endregion
    }
}
